CREATE TABLE public.plm_file_verifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, revision_id uuid NOT NULL, storage_path text NOT NULL, original_name text NOT NULL, mime_type text NOT NULL, size_bytes bigint NOT NULL, sha256 text NOT NULL, expires_at timestamptz NOT NULL, used_at timestamptz);
GRANT ALL ON public.plm_file_verifications TO service_role;
ALTER TABLE public.plm_file_verifications ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.plm_register_file(_revision uuid,_path text,_name text,_mime text,_size bigint,_hash text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.plm_revisions; fid uuid; receipt uuid; BEGIN SELECT * INTO r FROM public.plm_revisions WHERE id=_revision FOR UPDATE; IF NOT FOUND OR NOT public.plm_has_scope(r.organization_id,r.site_id) THEN RAISE EXCEPTION 'Unauthorized file scope'; END IF; IF r.state<>'DRAFT' OR (SELECT kind FROM public.plm_entities WHERE id=r.entity_id)<>'DOCUMENT' THEN RAISE EXCEPTION 'File attaches only to a draft document revision'; END IF; SELECT id INTO receipt FROM public.plm_file_verifications WHERE user_id=auth.uid() AND revision_id=_revision AND storage_path=_path AND original_name=_name AND mime_type=_mime AND size_bytes=_size AND sha256=_hash AND expires_at>now() AND used_at IS NULL FOR UPDATE; IF receipt IS NULL THEN RAISE EXCEPTION 'Server-verified file receipt required'; END IF; UPDATE public.plm_file_verifications SET used_at=now() WHERE id=receipt; INSERT INTO public.plm_document_files(revision_id,organization_id,site_id,storage_path,original_name,mime_type,size_bytes,sha256,uploaded_by) VALUES(_revision,r.organization_id,r.site_id,_path,_name,_mime,_size,_hash,auth.uid()) RETURNING id INTO fid; INSERT INTO public.plm_audit_events(organization_id,site_id,actor_id,action,revision_id,reason,after_value,content_hash) VALUES(r.organization_id,r.site_id,auth.uid(),'REGISTER_FILE',r.id,'Server-verified immutable controlled file',jsonb_build_object('file_id',fid,'sha256',_hash,'size',_size),r.content_hash); RETURN fid; END $$;
GRANT EXECUTE ON FUNCTION public.plm_register_file(uuid,text,text,text,bigint,text) TO authenticated;